const float pi = 3.14159265;
const float tau = 2.0 * pi;

void mainImage(out vec4 outColor, in vec2 inColor) {
  outColor = vec4(0.0);
  vec2 position = (2.0 * inColor.xy - iResolution.xy) / iResolution.y;

  float dist = length(position);
  float angle = atan(position.x, position.y) / tau;

  dist -= iTime;
  dist = abs(mod(2.0 * dist, 2.0) - 1.0);

  vec3 p = vec3(angle * 10.0 + iTime, dist + iTime, 0.0);
  float noise = perlinNoise(p, 3.0, 5, 0.75, 2.0);

  float h = 0.45 + dist / 2.0;
  float s = 1.0;
  float v = pow(dist, 3.0);
  vec3 color = hsv2rgb(vec3(h, s, v));

  outColor = vec4(noise) * vec4(color, 1.0);
}

// from https://www.shadertoy.com/view/MsS3Wc

vec3 hsv2rgb(in vec3 c) {
  vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
  return c.z * mix(vec3(1.0), rgb, c.y);
}

// from https://www.shadertoy.com/view/slB3z3

uint hash(uint x, uint seed) {
  const uint m = 0x5bd1e995U;
  uint hash = seed;

  uint k = x;
  k *= m;
  k ^= k >> 24;
  k *= m;
  hash *= m;
  hash ^= k;

  hash ^= hash >> 13;
  hash *= m;
  hash ^= hash >> 15;
  return hash;
}

uint hash(uvec3 x, uint seed) {
  const uint m = 0x5bd1e995U;
  uint hash = seed;

  uint k = x.x;
  k *= m;
  k ^= k >> 24;
  k *= m;
  hash *= m;
  hash ^= k;

  k = x.y;
  k *= m;
  k ^= k >> 24;
  k *= m;
  hash *= m;
  hash ^= k;

  k = x.z;
  k *= m;
  k ^= k >> 24;
  k *= m;
  hash *= m;
  hash ^= k;

  hash ^= hash >> 13;
  hash *= m;
  hash ^= hash >> 15;

  return hash;
}

vec3 gradientDirection(uint hash) {
  switch(int(hash) & 15) {
    case 0:
      return vec3(1, 1, 0);
    case 1:
      return vec3(-1, 1, 0);
    case 2:
      return vec3(1, -1, 0);
    case 3:
      return vec3(-1, -1, 0);
    case 4:
      return vec3(1, 0, 1);
    case 5:
      return vec3(-1, 0, 1);
    case 6:
      return vec3(1, 0, -1);
    case 7:
      return vec3(-1, 0, -1);
    case 8:
      return vec3(0, 1, 1);
    case 9:
      return vec3(0, -1, 1);
    case 10:
      return vec3(0, 1, -1);
    case 11:
      return vec3(0, -1, -1);
    case 12:
      return vec3(1, 1, 0);
    case 13:
      return vec3(-1, 1, 0);
    case 14:
      return vec3(0, -1, 1);
    case 15:
      return vec3(0, -1, -1);
  }
}

float interpolate(float v1, float v2, float v3, float v4, float v5, float v6, float v7, float v8, vec3 t) {
  return mix(mix(mix(v1, v2, t.x), mix(v3, v4, t.x), t.y), mix(mix(v5, v6, t.x), mix(v7, v8, t.x), t.y), t.z);
}

vec3 fade(vec3 t) {
  return t * t * t * (t * (t * 6.0 - 15.0) + 10.0);
}

float perlinNoise(vec3 position, uint seed) {
  position = abs(position);
  vec3 floorPosition = floor(position);
  vec3 fractPosition = position - floorPosition;
  uvec3 cellCoordinates = uvec3(floorPosition);
  float v1 = dot(gradientDirection(hash(cellCoordinates, seed)), fractPosition);
  float v2 = dot(gradientDirection(hash((cellCoordinates + uvec3(1, 0, 0)), seed)), fractPosition - vec3(1, 0, 0));
  float v3 = dot(gradientDirection(hash((cellCoordinates + uvec3(0, 1, 0)), seed)), fractPosition - vec3(0, 1, 0));
  float v4 = dot(gradientDirection(hash((cellCoordinates + uvec3(1, 1, 0)), seed)), fractPosition - vec3(1, 1, 0));
  float v5 = dot(gradientDirection(hash((cellCoordinates + uvec3(0, 0, 1)), seed)), fractPosition - vec3(0, 0, 1));
  float v6 = dot(gradientDirection(hash((cellCoordinates + uvec3(1, 0, 1)), seed)), fractPosition - vec3(1, 0, 1));
  float v7 = dot(gradientDirection(hash((cellCoordinates + uvec3(0, 1, 1)), seed)), fractPosition - vec3(0, 1, 1));
  float v8 = dot(gradientDirection(hash((cellCoordinates + uvec3(1, 1, 1)), seed)), fractPosition - vec3(1, 1, 1));
  return interpolate(v1, v2, v3, v4, v5, v6, v7, v8, fade(fractPosition));
}

float perlinNoise(vec3 position, float frequency, int octaves, float amplitudeFactor, float frequencyFactor) {
  float value = 0.0;
  float amplitude = 1.0;
  uint seed = 0x0U;

  position = abs(position);

  for(int i = 0; i < octaves; i++) {
    seed = hash(seed, 0x0U);
    value += perlinNoise(position * frequency, seed) * amplitude;
    amplitude *= amplitudeFactor;
    frequency *= frequencyFactor;
  }

  value = (value + 1.0) * 0.5;

  return value;
}
